import yaml, pathlib
p=pathlib.Path('pipeline_config.example.yaml')
assert p.exists(), 'missing pipeline_config.example.yaml'
obj=yaml.safe_load(p.read_text(encoding='utf-8')) or {}
# Accept either top-level hf_token or nested align_make.hf_token
vals=[]
if isinstance(obj, dict):
    if 'hf_token' in obj: vals.append(obj.get('hf_token'))
    am=obj.get('align_make', {}) if isinstance(obj.get('align_make', {}), dict) else {}
    vals.append(am.get('hf_token'))
for v in vals:
    if v is None: continue
    assert str(v).strip() in ('', 'YOUR_HF_TOKEN_HERE'), f'hf token not placeholder: {v!r}'
print('ok')
